const AnalyticsChart = lazy(
  () => import("./AnalyticsChart")
);

function Dashboard({ showAnalytics }) {
  return (
    <div>
      <h1>Dashboard</h1>

      {showAnalytics && (
        <Suspense fallback={<p>Loading chart...</p>}>
          <AnalyticsChart />
        </Suspense>
      )}
    </div>
  );
}

// AnalyticsChart is loaded only when it is rendered.
